challenges.solution:
def word_counts(text):
    counts = {}
    for word in text.lower().split():
        counts[word] = counts.get(word, 0) + 1
    return counts

def top_student(scores):
    best = None
    for name, score in scores.items():
        if best is None or score > scores[best]:
            best = name
    return best

def dedupe(items):
    seen = set()
    result = []
    for x in items:
        if x not in seen:
            seen.add(x)
            result.append(x)
    return result

def group_by_grade(grades):
    groups = {}
    for name in sorted(grades):
        groups.setdefault(grades[name], []).append(name)
    return groups
